const slug=(v:string)=>slugify(v,{lower:true,strict:true});
const generateUniqueProductSlug=async(rawName:string,excludeId?:string):Promise<string>=>{
  let base=slug(rawName);
  if(!base||base.length<2)base='poster-'+crypto.randomBytes(3).toString('hex');
  let candidate=base;let counter=1;
  while(true){
    const query:any={slug:candidate};
    if(excludeId)query._id={$ne:excludeId};
    const exists=await Product.exists(query);
    if(!exists)return candidate;
    counter++;candidate=`${base}-${counter}`;
  }
};
