api.get('/products',wrap(async(req,res)=>{
  const filter:any={active:true,inventoryVerified:true};
  if(req.query.category)filter.category=String(req.query.category).slice(0,100);
  if(req.query.search){const raw=String(req.query.search).trim().slice(0,100);const term=raw.split('').map(ch=>/[\p{L}\p{N} ]/u.test(ch)?ch:' ').join('').trim();if(term)filter.$or=[{name:{$regex:term,$options:'i'}},{category:{$regex:term,$options:'i'}},{description:{$regex:term,$options:'i'}},{quote:{$regex:term,$options:'i'}}]}
  if(req.query.featured==='true')filter.featured=true;
   const variantFilter:any={active:{$ne:false},stock:{$gt:0}};if(req.query.size)variantFilter.size=String(req.query.size).slice(0,40);if(req.query.paperQuality)variantFilter.paperQuality=String(req.query.paperQuality).slice(0,80);if(req.query.finish)variantFilter.finish=String(req.query.finish).slice(0,80);if(req.query.inStock==='true')variantFilter.stock={$gt:0};
  const minPrice=Number(req.query.minPrice),maxPrice=Number(req.query.maxPrice);if(Number.isFinite(minPrice)&&minPrice>0||Number.isFinite(maxPrice)&&maxPrice>0){variantFilter.price={};if(Number.isFinite(minPrice)&&minPrice>0)variantFilter.price.$gte=minPrice;if(Number.isFinite(maxPrice)&&maxPrice>0)variantFilter.price.$lte=maxPrice}if(Object.keys(variantFilter).length)filter.variants={$elemMatch:variantFilter};
  const page=Math.max(1,Number(req.query.page)||1),pageSize=Math.min(100,Math.max(1,Number(req.query.pageSize)||Number(req.query.limit)||24)),minRating=Math.min(5,Math.max(0,Number(req.query.minRating)||0));
  const sortKey=String(req.query.sort||'featured');const sort:any=sortKey==='price-low'?{'variants.price':1}:sortKey==='price-high'?{'variants.price':-1}:sortKey==='newest'?{createdAt:-1}:sortKey==='popular'?{reviewCount:-1,averageRating:-1,createdAt:-1}:sortKey==='rating'?{averageRating:-1,reviewCount:-1,createdAt:-1}:{featured:-1,createdAt:-1};
  const base:any[]=[{$match:filter},{$lookup:{from:'reviews',let:{productId:'$_id'},pipeline:[{$match:{$expr:{$and:[{$eq:['$product','$$productId']},{$eq:['$approved',true]}]}}},{$group:{_id:null,averageRating:{$avg:'$rating'},reviewCount:{$sum:1}}}],as:'reviewStats'}},{$addFields:{averageRating:{$ifNull:[{$arrayElemAt:['$reviewStats.averageRating',0]},0]},reviewCount:{$ifNull:[{$arrayElemAt:['$reviewStats.reviewCount',0]},0]}}}];
  if(minRating>0)base.push({$match:{averageRating:{$gte:minRating}}});
  const [rows,count]=await Promise.all([Product.aggregate([...base,{$sort:sort},{$skip:(page-1)*pageSize},{$limit:pageSize}]),Product.aggregate([...base,{$count:'total'}])]);
  const products=rows.map((product:any)=>({...product,variants:product.variants.filter((variant:any)=>variant.active!==false)}));const total=count[0]?.total||0;res.json({products,pagination:{page,pageSize,total,pages:Math.ceil(total/pageSize)}});
}));
