api.post('/orders/:id/cancel',auth,wrap(async(req:AuthRequest,res:any)=>{const order=await Order.findOne({_id:req.params.id,user:req.user!.id,channel:'online'});if(!order)return res.status(404).json({error:'Order not found'});if(order.paymentStatus==='paid')return res.status(409).json({error:'Paid orders must be handled by store support'});const cancelled=await Order.findOneAndUpdate({_id:order._id,status:{$in:['Pending','Confirmed']},paymentStatus:{$ne:'paid'},stockRestored:{$ne:true}},{$set:{status:'Cancelled',paymentStatus:'failed',stockRestored:true},$push:{statusHistory:{status:'Cancelled',at:new Date(),note:'Cancelled by customer'}}},{new:true});if(!cancelled)return res.status(409).json({error:'This order can no longer be cancelled'});for(const item of cancelled.items)await Product.updateOne({_id:item.product},{$inc:{'variants.$[variant].stock':item.quantity}},{arrayFilters:[{'variant.size':item.size,'variant.paperQuality':item.paperQuality,'variant.finish':item.finish,'variant.frame':item.frame||''}]});res.json({order:cancelled})}));
api.post('/orders/:id/return',auth,wrap(async(req:AuthRequest,res:any)=>{const body=z.object({reason:z.string().trim().min(10).max(1200)}).parse(req.body);const order=await Order.findOne({_id:req.params.id,user:req.user!.id,channel:'online'});if(!order)return res.status(404).json({error:'Order not found'});if(order.status!=='Delivered')return res.status(409).json({error:'Return requests are available after delivery'});const record=await ReturnRequest.findOneAndUpdate({order:order._id,user:req.user!.id},{$setOnInsert:{order:order._id,user:req.user!.id,orderNumber:order.orderNumber,reason:body.reason,status:'pending'}},{upsert:true,new:true,runValidators:true});if(record.reason!==body.reason&&record.status!=='pending')return res.status(409).json({error:'A return request already exists for this order'});res.status(201).json({returnRequest:record})}));
