api.put('/cart',auth,wrap(async(req:AuthRequest,res:any)=>{const v=z.object({items:z.array(z.object({productId:z.string(),size:z.string(),paperQuality:z.string(),finish:z.string(),frame:z.string().optional(),quantity:z.number().int().min(1).max(50)})).max(100)}).parse(req.body);const items:any[]=[];for(const item of v.items){const product=await Product.findOne({_id:item.productId,active:true,inventoryVerified:true});const variant=product?.variants.find((candidate:any)=>candidate.active!==false&&candidate.size===item.size&&candidate.paperQuality===item.paperQuality&&candidate.finish===item.finish&&(candidate.frame||'')===(item.frame||''));if(!product||!variant)throw Object.assign(new Error('Cart mein unavailable variant hai'),{status:409});items.push({product:product._id,size:variant.size,paperQuality:variant.paperQuality,finish:variant.finish,frame:variant.frame||'',quantity:Math.min(item.quantity,variant.stock)});}const cart=await Cart.findOneAndUpdate({user:req.user!.id},{user:req.user!.id,items:items.filter(item=>item.quantity>0)},{upsert:true,new:true}).populate('items.product');res.json({cart})}));
api.post('/orders',auth,wrap(async(req:AuthRequest,res:any)=>{const v=z.object({items:z.array(z.object({productId:z.string(),variant:z.object({size:z.string(),paperQuality:z.string(),finish:z.string()}),quantity:z.number().int().min(1).max(50)})).min(1),shippingAddress:z.object({name:z.string().min(2),phone:z.string().min(10),line1:z.string().min(5),line2:z.string().optional(),email:z.email().optional(),city:z.string().min(2),state:z.string().min(2),postalCode:z.string().min(6).max(10),deliveryInstructions:z.string().max(500).optional(),country:z.string().default('India')}),paymentMethod:z.enum(['razorpay','cod']),couponCode:z.string().optional()}).parse(req.body);const idempotencyKey=req.header('Idempotency-Key')||crypto.randomUUID();const prior=await Order.findOne({user:req.user!.id,idempotencyKey});if(prior)return res.json({order:prior});if(v.paymentMethod==='razorpay'&&(!process.env.RAZORPAY_KEY_ID||!process.env.RAZORPAY_KEY_SECRET))return res.status(503).json({error:'Online payment setup pending; choose Cash on Delivery'});const order=await createOrder(v.items,v.shippingAddress,String(req.user!.id),v.paymentMethod,v.couponCode,undefined,0,idempotencyKey);if(v.paymentMethod==='razorpay'){try{const rz:any=new Razorpay({key_id:process.env.RAZORPAY_KEY_ID,key_secret:process.env.RAZORPAY_KEY_SECRET});const payment:any=await rz.orders.create({amount:Math.round(order.total*100),currency:'INR',receipt:order.orderNumber});order.paymentReference=payment.id;await order.save();return res.status(201).json({order,payment:{id:payment.id,key:process.env.RAZORPAY_KEY_ID,amount:payment.amount,currency:payment.currency}})}catch(error){await restoreReservedStock(order);order.paymentStatus='failed';order.status='Cancelled';await order.save();throw error}}await sendOrderNotice(order);res.status(201).json({order})}));
api.post('/payments/verify',auth,wrap(async(req:AuthRequest,res:any)=>{const v=z.object({orderId:z.string(),razorpay_order_id:z.string(),razorpay_payment_id:z.string(),razorpay_signature:z.string().length(64)}).parse(req.body);const order=await Order.findOne({_id:v.orderId,user:req.user!.id,paymentReference:v.razorpay_order_id});if(!order)return res.status(404).json({error:'Payment order not found'});if(order.paymentStatus==='failed'||order.stockRestored)return res.status(409).json({error:'This payment order has already been closed'});if(order.paymentStatus==='paid')return res.json({order});const expected=crypto.createHmac('sha256',process.env.RAZORPAY_KEY_SECRET||'').update(`${v.razorpay_order_id}|${v.razorpay_payment_id}`).digest('hex');if(!crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(v.razorpay_signature)))return res.status(400).json({error:'Payment signature verification failed'});order.paymentStatus='paid';order.paymentReference=v.razorpay_payment_id;order.status='Confirmed';await order.save();await sendOrderNotice(order);res.json({order})}));
