const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024,files:5},fileFilter:(_req,file,cb)=>/^image\/(jpe?g|png|webp)$/i.test(file.mimetype)?cb(null,true):cb(new Error('Only JPEG, PNG or WebP images are allowed'))});
function detectedImage(file:Express.Multer.File){const b=file.buffer;if(b.length>=3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff)return {mime:'image/jpeg',ext:'.jpg'};if(b.length>=8&&b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))return {mime:'image/png',ext:'.png'};if(b.length>=12&&b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WEBP')return {mime:'image/webp',ext:'.webp'};return null;}
const customUploadLimiter=rateLimit({windowMs:60*60*1000,limit:8,standardHeaders:true,legacyHeaders:false,message:{error:'Upload limit reached. Try again later.'}});
const privateCustomDir=()=>path.resolve(process.env.CUSTOM_REQUEST_UPLOAD_DIR||path.resolve(process.cwd(),'..','.panditji-private-custom-requests'));
const requestNumber=()=>`PJC-${new Date().getFullYear()}-${crypto.randomBytes(5).toString('hex').toUpperCase()}`;
const accessDigest=(token:string)=>crypto.createHash('sha256').update(token).digest('hex');
const customAccessUrl=(token:string)=>`${(process.env.CLIENT_URL||'http://localhost:5173').replace(/\/$/,'')}/custom-poster?access=${encodeURIComponent(token)}`;
api.post('/custom-requests',customUploadLimiter,upload.single('image'),wrap(async(req,res)=>{
  const file=(req as any).file as Express.Multer.File|undefined;if(!file)return res.status(400).json({error:'Upload your reference photo to continue'});
  const type=detectedImage(file);if(!type||type.mime!==file.mimetype)return res.status(400).json({error:'Image content does not match an allowed JPEG, PNG or WebP file'});
  const schema=z.object({name:z.string().trim().min(2).max(100),phone:z.string().trim().regex(/^\+?[0-9 ()-]{10,18}$/),whatsapp:z.string().trim().regex(/^\+?[0-9 ()-]{10,18}$/).optional().or(z.literal('')),email:z.union([z.email(),z.literal('')]).optional(),category:z.string().trim().min(2).max(80),title:z.string().trim().min(2).max(180),size:z.string().trim().min(1).max(40),paperQuality:z.string().trim().min(1).max(80),finish:z.string().trim().min(1).max(80),frame:z.string().trim().min(1).max(80),quantity:z.coerce.number().int().min(1).max(50),address:z.string().trim().min(5).max(500),city:z.string().trim().min(2).max(80),state:z.string().trim().min(2).max(80),postalCode:z.string().trim().regex(/^\d{6}$/),instructions:z.string().trim().max(1500).optional().default(''),consent:z.literal('true')}).parse(req.body);
  const token=crypto.randomBytes(32).toString('hex');const imageName=`${crypto.randomUUID()}${type.ext}`;await mkdir(privateCustomDir(),{recursive:true});await writeFile(path.join(privateCustomDir(),imageName),file.buffer,{flag:'wx',mode:0o600});
  let request:any;try{request=await CustomRequest.create({...schema,name:schema.name,email:schema.email||undefined,whatsapp:schema.whatsapp||undefined,originalImage:imageName,requestNumber:requestNumber(),accessHashes:[accessDigest(token)],consent:true,status:'New'})}catch(error){await import('node:fs/promises').then(fs=>fs.unlink(path.join(privateCustomDir(),imageName)).catch(()=>{}));throw error}
  await Notification.create({type:'custom-request',title:`New custom poster request ${request.requestNumber}`,message:`${request.name} · ${request.category} · ${request.quantity} copy/copies`});
  const notification=await sendCustomRequestNotice(request,customAccessUrl(token),'received');request.notification=notification;await request.save();
  res.status(201).json({requestNumber:request.requestNumber,status:request.status,accessToken:token,notification});
}));
