api.post('/custom-requests/access/:token/decision',customUploadLimiter,wrap(async(req,res)=>{const token=String(req.params.token);const body=z.object({decision:z.enum(['approve','changes']),feedback:z.string().trim().max(1500).optional().default('')}).parse(req.body);const request=await CustomRequest.findOne({accessHashes:accessDigest(token)}).select('+accessHashes');if(!request)return res.status(404).json({error:'Request link is invalid'});if(request.status!=='Quotation Sent'&&request.status!=='Awaiting Approval')return res.status(409).json({error:'There is no quotation awaiting your response'});if(body.decision==='approve'&&!request.finalPreview)return res.status(409).json({error:'The final design preview is not ready yet'});request.customerFeedback=body.feedback;request.status=body.decision==='approve'?'Approved':'Changes Requested';request.approvedAt=body.decision==='approve'?new Date():undefined;await request.save();await Notification.create({type:'custom-request-update',title:'Customer '+(body.decision==='approve'?'approved':'requested changes')+' · '+request.requestNumber,message:request.name+' · '+request.title});res.json({requestNumber:request.requestNumber,status:request.status,message:body.decision==='approve'?'Design approved. The shop will now confirm the order.':'Change request sent to the shop.'})}));
