api.patch('/admin/custom-requests/:id',...admin,wrap(async(req,res)=>{const body=z.object({action:z.enum(['review','reject','quote','status']).optional(),status:z.enum(['New','Reviewing','Quotation Sent','Awaiting Approval','Approved','Confirmed','Printing','Shipped','Delivered','Rejected']).optional(),internalNotes:z.string().trim().max(3000).optional(),designCategory:z.string().trim().max(80).optional(),design:z.string().trim().max(1000).optional(),finalPrice:z.number().positive().optional(),estimatedDelivery:z.string().trim().max(120).optional()}).parse(req.body);const request=await CustomRequest.findById(req.params.id).select('+accessHashes');if(!request)return res.status(404).json({error:'Request not found'});if(body.action==='quote'&&(!request.finalPreview||!body.finalPrice||!body.estimatedDelivery))return res.status(400).json({error:'Upload the final preview and set a price and estimated delivery before sending a quotation'});if(body.action==='review')request.status='Reviewing';if(body.action==='reject')request.status='Rejected';if(body.action==='quote')request.status='Quotation Sent';if(body.status)request.status=body.status;for(const key of ['internalNotes','designCategory','design','finalPrice','estimatedDelivery'] as const)if(body[key]!==undefined)(request as any)[key]=body[key];await request.save();if(body.status&&request.order){const linkedOrder=await Order.findById(request.order);if(linkedOrder){linkedOrder.status=body.status as any;linkedOrder.statusHistory.push({status:body.status,at:new Date(),note:'Custom poster '+request.requestNumber+' update'});await linkedOrder.save();await notifyOrderChange(String(linkedOrder._id))}}let notification={email:false,whatsapp:false,configured:{email:false,whatsapp:false}},accessUrl='';if(body.action==='quote'||body.action==='reject'){const token=crypto.randomBytes(32).toString('hex');request.accessHashes.push(accessDigest(token));await request.save();accessUrl=customAccessUrl(token);notification=await sendCustomRequestNotice(request,accessUrl,body.action==='quote'?'quotation':'rejected')}const safeRequest=request.toObject();delete safeRequest.accessHashes;res.json({request:safeRequest,notification,accessUrl})}));
api.post('/admin/custom-requests/:id/confirm',...admin,wrap(async(req,res)=>{const request=await CustomRequest.findById(req.params.id).select('+accessHashes');if(!request)return res.status(404).json({error:'Request not found'});if(request.status!=='Approved'&&request.status!=='Confirmed')return res.status(409).json({error:'Customer approval is required before confirming this custom order'});if(request.order){const order=await Order.findById(request.order);return res.json({order,duplicate:true})}const settings=await AdminSettings.findOne({key:'codCharge'}).lean();const deliveryCharge=Number.isFinite(Number(settings?.value))?Number(settings?.value):COD_CHARGE;const subtotal=(request.finalPrice||0)*request.quantity;if(!subtotal)return res.status(409).json({error:'A valid quotation is required'});const orderNumber=`PJ-${new Date().getFullYear()}-${crypto.randomBytes(8).toString('hex').toUpperCase()}`;try{const order=await Order.create({orderNumber,customRequest:request._id,customer:{name:request.name,email:request.email,phone:request.phone},shippingAddress:{name:request.name,phone:request.phone,line1:request.address,city:request.city,state:request.state,postalCode:request.postalCode,country:'India'},items:[{name:`Custom poster: ${request.title}`,slug:'custom-poster',size:request.size,paperQuality:request.paperQuality,finish:request.finish,frame:request.frame,unitPrice:request.finalPrice,quantity:request.quantity,image:''}],subtotal,deliveryCharge,total:subtotal+deliveryCharge,paymentMethod:'cod',paymentStatus:'pending',status:'Confirmed',channel:'online',notes:`Custom request ${request.requestNumber}. ${request.design||''}`,statusHistory:[{status:'Pending',at:new Date(),note:`Confirmed from approved custom request ${request.requestNumber}`} ]});request.order=order._id;request.status='Confirmed';const accessToken=crypto.randomBytes(32).toString('hex');request.accessHashes.push(accessDigest(accessToken));await request.save();const accessUrl=customAccessUrl(accessToken);const customerNotification=await sendCustomRequestNotice({...request.toObject(),order},accessUrl,'approved');request.notification=customerNotification;await request.save();await Notification.create({type:'new-order',title:'Custom order '+order.orderNumber,message:request.requestNumber+' / '+request.name,order:order._id});await sendOrderNotice(order);res.status(201).json({order,duplicate:false,notification:customerNotification,accessUrl})}catch(error:any){if(error?.code===11000){const existing=await Order.findOne({customRequest:request._id});if(existing){request.order=existing._id;request.status='Confirmed';await request.save();return res.json({order:existing,duplicate:true})}}throw error}}));
api.post('/admin/uploads',...admin,upload.array('images',5),wrap(async(req,res)=>{const files=(req.files||[]) as Express.Multer.File[];if(!files.length)return res.status(400).json({error:'Image files required'});const checked=files.map(file=>{const type=detectedImage(file);const match=type&&(type.mime===file.mimetype||(type.mime==='image/jpeg'&&file.mimetype==='image/jpg'));if(!type||!match)throw Object.assign(new Error('Image content does not match an allowed JPEG, PNG or WebP file.'),{status:400});return {file,type}});const cloudEnabled=Boolean(process.env.CLOUDINARY_CLOUD_NAME&&process.env.CLOUDINARY_API_KEY&&process.env.CLOUDINARY_API_SECRET);let images:string[];if(cloudEnabled){const cloud=configureCloudinary();images=await Promise.all(checked.map(({file})=>new Promise<string>((resolve,reject)=>{const stream=cloud.uploader.upload_stream({folder:'panditji-posters',resource_type:'image'},(err,result)=>err?reject(err):resolve(result!.secure_url));stream.end(file.buffer)})))}else{const directory=path.resolve(process.cwd(),'uploads','products');await mkdir(directory,{recursive:true});images=await Promise.all(checked.map(async({file,type})=>{const name=`${crypto.randomUUID()}${type.ext}`;await writeFile(path.join(directory,name),file.buffer,{flag:'wx',mode:0o644});return `/uploads/products/${name}`}))}res.status(201).json({images,storage:cloudEnabled?'cloud':'local'})}));
export async function createOrder(items:any[],address:any,userId:string,paymentMethod:string,couponCode?:string,customer?:any,discountInput=0,idempotencyKey?:string){
  let subtotal=0;const lines:any[]=[];
  for(const item of items){
    const product=await Product.findOne({_id:item.productId,active:true,inventoryVerified:true});
    if(!product)throw Object.assign(new Error('A product is unavailable'),{status:400});
    const variant=product.variants.find((v:any)=>v.active!==false&&v.size===item.variant.size&&v.paperQuality===item.variant.paperQuality&&v.finish===item.variant.finish&&(v.frame||'')===(item.variant.frame||''));
    if(!variant||variant.stock<item.quantity)throw Object.assign(new Error(`${product.name}: selected size is unavailable or low in stock`),{status:409});
    const unitPrice=product.discountPrice&&product.discountPrice<variant.price?product.discountPrice:variant.price;
    subtotal+=unitPrice*item.quantity;lines.push({product,variant,quantity:item.quantity,unitPrice});
  }
  let discount=Math.max(0,Math.min(discountInput,subtotal));let coupon:any=null;
  if(couponCode){
    coupon=await Coupon.findOne({code:couponCode.toUpperCase(),active:true});
    if(!coupon||coupon.expiresAt&&coupon.expiresAt<new Date()||coupon.startsAt&&coupon.startsAt>new Date()||coupon.usageLimit&&coupon.usedCount>=coupon.usageLimit||subtotal<(coupon.minOrder||0))throw Object.assign(new Error('Coupon invalid or order minimum not met'),{status:400});
    discount=Math.min(subtotal,coupon.type==='percent'?subtotal*coupon.value/100:coupon.value,coupon.maxDiscount||subtotal);
  }
  const configRows=await AdminSettings.find({key:{$in:['codCharge','onlineDiscount','shippingCharge','freeShippingMinimum']}}).lean();const config=Object.fromEntries(configRows.map((x:any)=>[x.key,Number(x.value)]));const codCharge=Number.isFinite(config.codCharge)?config.codCharge:COD_CHARGE;const onlineDiscount=Number.isFinite(config.onlineDiscount)?config.onlineDiscount:ONLINE_PAYMENT_DISCOUNT;const shippingCharge=Number.isFinite(config.shippingCharge)?config.shippingCharge:COD_CHARGE;const freeMinimum=Number.isFinite(config.freeShippingMinimum)?config.freeShippingMinimum:999;
  if(paymentMethod==='razorpay')discount=Math.min(subtotal,discount+onlineDiscount);
  const deliveryCharge=paymentMethod==='cod'?codCharge:(subtotal-discount>=freeMinimum?0:shippingCharge);const user=customer?null:await User.findById(userId);const reserved:any[]=[];
  try{
    for(const line of lines){
      const frameMatch={$in:[line.variant.frame||'',null]};
      const result=await Product.updateOne({_id:line.product._id,variants:{$elemMatch:{size:line.variant.size,paperQuality:line.variant.paperQuality,finish:line.variant.finish,frame:frameMatch,active:{$ne:false},stock:{$gte:line.quantity}}}},{$inc:{'variants.$[variant].stock':-line.quantity}},{arrayFilters:[{'variant.size':line.variant.size,'variant.paperQuality':line.variant.paperQuality,'variant.finish':line.variant.finish,'variant.frame':frameMatch,'variant.active':{$ne:false},'variant.stock':{$gte:line.quantity}}]});
      if(result.modifiedCount!==1)throw Object.assign(new Error(`${line.product.name}: stock changed while checking out; please retry`),{status:409});reserved.push(line);
    }
    const order=await Order.create({orderNumber:`PJ-${new Date().getFullYear()}-${crypto.randomBytes(8).toString('hex').toUpperCase()}`,idempotencyKey,user:user?._id,customer:customer||{name:address.name||user?.name,email:address.email||user?.email,phone:address.phone||user?.phone},shippingAddress:address,items:lines.map(x=>({product:x.product._id,name:x.product.name,slug:x.product.slug,size:x.variant.size,paperQuality:x.variant.paperQuality,finish:x.variant.finish,frame:x.variant.frame,unitPrice:x.unitPrice,quantity:x.quantity,image:x.product.images[0]})),subtotal,deliveryCharge,discount,total:Math.max(0,subtotal+deliveryCharge-discount),paymentMethod:paymentMethod==='offline'?'cash':paymentMethod,paymentStatus:'pending',status:'Pending',channel:paymentMethod==='offline'?'offline':'online',couponCode,statusHistory:[{status:'Pending',at:new Date()}]});
    if(coupon){coupon.usedCount+=1;await coupon.save();}
    return order;
  }catch(error){
    await Promise.all(reserved.map(line=>Product.updateOne({_id:line.product._id},{$inc:{'variants.$[variant].stock':line.quantity}},{arrayFilters:[{'variant.size':line.variant.size,'variant.paperQuality':line.variant.paperQuality,'variant.finish':line.variant.finish,'variant.frame':{$in:[line.variant.frame||'',null]}}]})));
    throw error;
  }
}
async function restoreReservedStock(order:any){
  if(order.stockRestored)return;
  for(const item of order.items){
    await Product.updateOne({_id:item.product},{$inc:{'variants.$[variant].stock':item.quantity}},{arrayFilters:[{'variant.size':item.size,'variant.paperQuality':item.paperQuality,'variant.finish':item.finish,'variant.frame':item.frame||''}]});
  }
  order.stockRestored=true;
}
function makeToken(user:any){const secret=process.env.JWT_SECRET;if(!secret||secret.length<32)throw new Error('JWT_SECRET must be set to 32+ characters');return jwt.sign({id:String(user._id),role:user.role,email:user.email},secret,{expiresIn:process.env.JWT_EXPIRES_IN||'7d'} as jwt.SignOptions)}
